xpath.attribute:
#{link_class or ''} #{'active' if submenu.clean_url() and (
    unslug_url(request.httprequest.path) == unslug_url(submenu.clean_url())
    or (request.params.get('type') == 'sample' and 'type=sample' in submenu.clean_url())
) else ''}

#{item_class or ''} dropdown #{
    (
        (submenu.clean_url() and submenu.clean_url() != '/' and any(request.httprequest.path == child.url for child in submenu.child_id if child.url))
        or (submenu.clean_url() and request.httprequest.path == submenu.clean_url())
        or (request.params.get('type') == 'sample' and submenu.clean_url() and 'type=sample' in submenu.clean_url())
    ) and 'active'
} #{submenu.is_mega_menu and 'position-static'}
